#!/usr/bin/env python3
"""Recon-tree tool of a sealed source reference (GENERATED by `forge init --sealed-ref`,
copied in as sealref.py; see forgekernel.sealref).

The reference is a SOL-ExecBench / FlashInfer-Bench Python solution (PyTorch, Triton,
CuTe DSL; one file or many) sealed into ref_bin/ref_payload.bin. The key is in this
tree's gitignored submit.local.toml [env] only and reaches the job as an environment
variable; eval/closed_ref.py decodes the payload in memory, inside the job. No plaintext
of the reference is in this tree.

    python3 sealref.py check        load the reference, run it once on the card's inputs
    python3 sealref.py crosscheck   judge it with the card's own judge: must PASS
    python3 sealref.py bench        time it on the card's clock (the card's --mode ref JSON)
    python3 sealref.py ncu          NCU window: warm calls, then calls inside profiler start/stop
"""
from __future__ import annotations

import hashlib
import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
META = json.loads((HERE / "sealref.json").read_text())
PAYLOAD = HERE / "ref_bin" / "ref_payload.bin"


def _lb():
    sys.path.insert(0, str(HERE / "eval"))
    import leaderboard  # the card's judge, inputs and clock (a verbatim copy)
    return leaderboard


def _provenance() -> None:
    got = hashlib.sha256(PAYLOAD.read_bytes()).hexdigest()
    ok = got == META.get("payload_sha256")
    print(f"[sealref] payload sha256 {got} ({'matches sealref.json' if ok else 'DIFFERS from sealref.json'}); "
          f"module {META['module']}, entry {META['entry']}, {META.get('files')} file(s), "
          f"languages {META.get('languages')}")


def check() -> int:
    _provenance()
    lb = _lb()
    problem = lb.load_problem()
    fn, dps = lb._impl(problem, "ref")
    inp = lb.first_inputs(problem, "cuda")
    outs = lb.call_impl(problem, fn, inp, dps, "cuda", no_grad=True)
    print("[sealref] check ok:", [tuple(o.shape) for o in outs])
    return 0


def crosscheck() -> int:
    _provenance()
    lb = _lb()
    problem = lb.load_problem()
    fn, dps = lb._impl(problem, "ref")
    verdict, _ = lb.judge_workloads(problem, fn, dps, "cuda")  # every workload of a group card
    print(f"[sealref] crosscheck {'PASS' if verdict['pass'] else 'FAIL'}: {verdict['status']}"
          + (f" — {verdict.get('error')}" if not verdict["pass"] else ""))
    return 0 if verdict["pass"] else 1


def bench() -> int:
    return _lb().run_leaderboard_bench(["--mode", "ref"])


def ncu() -> int:
    _lb().ncu_window(which="ref")
    return 0


if __name__ == "__main__":
    cmd = sys.argv[1] if len(sys.argv) > 1 else ""
    fns = {"check": check, "crosscheck": crosscheck, "bench": bench, "ncu": ncu}
    if cmd not in fns:
        print(__doc__)
        raise SystemExit(2)
    raise SystemExit(fns[cmd]())
